#!/bin/bash
# Pre-commit hook to prevent committing generated files
# Based on CLAUDE.md Rule 1: Never Commit Generated Files
#
# This hook enforces the repository's Constitution: generated files must not be
# edited by themselves. A source change may carry its regenerated output so CI's
# Validate Docs Generation job can prove the committed tree is reproducible.

set -e

# Define patterns for generated files that should never be committed manually
# These files are created by CI/CD workflows from generators in tools/
GENERATED_PATTERNS=(
  # Provider documentation - generated by tfplugindocs + transform-docs.go (on-merge.yml)
  "^docs/resources/.*\.md$"
  "^docs/data-sources/.*\.md$"
  "^docs/functions/.*\.md$"
  "^docs/guides/.*\.md$"
  # Provider Go code - generated by generate-all-schemas.go (on-merge.yml)
  "^internal/provider/.*_resource\.go$"
  "^internal/provider/.*_data_source\.go$"
  # Example Terraform files - generated by generate-examples.go (on-merge.yml)
  # Note: examples/functions/ is MANUALLY maintained (source for function doc generation)
  # Note: examples/guides/ is MANUALLY maintained (source for guide doc generation)
  "^examples/resources/.*\.tf$"
  "^examples/data-sources/.*\.tf$"
)

# Manually maintained files that are EXCEPTIONS to the generated patterns
# These data sources are not auto-generated from OpenAPI specs - they provide
# utility functionality not available in the F5 specifications
MANUALLY_MAINTAINED_FILES=(
  "internal/provider/functions_registration.go"
  "internal/provider/addon_service_data_source.go"
  "internal/provider/addon_service_activation_status_data_source.go"
  "internal/provider/site_registration_data_source.go"
  "examples/data-sources/addon_service/data-source.tf"
  "examples/data-sources/addon_service_activation_status/data-source.tf"
  "examples/data-sources/site_registration/data-source.tf"
  # MkDocs documentation site index files (navigation, not provider docs)
  "docs/resources/index.md"
  "docs/data-sources/index.md"
  "docs/functions/index.md"
  "docs/guides/index.md"
)

# These are the same generator-source boundaries enforced by ci.yml's
# Constitution Check. Keep the two lists in sync.
GENERATOR_SOURCE_PATTERNS=(
  "^tools/transform-docs\.go$"
  "^tools/generate-"
  "^tools/normalize-"
  "^tools/pkg/codegen/"
  "^tools/pkg/description/"
  "^tools/pkg/docfmt/"
  "^tools/pkg/resource/"
  "^templates/"
  "^Makefile$"
  "^\.github/workflows/ci\.yml$"
  "^internal/provider/addon_service"
  "^internal/provider/site_registration"
  "^internal/provider/functions_registration"
)

ALLOWED_WITH_GENERATORS=(
  "^docs/resources/.*\.md$"
  "^docs/data-sources/.*\.md$"
  "^docs/functions/.*\.md$"
  "^docs/guides/.*\.md$"
  "^docs/index\.md$"
  "^examples/resources/.*\.tf$"
  "^examples/data-sources/.*\.tf$"
  "^internal/provider/.*_resource\.go$"
  "^internal/provider/.*_data_source\.go$"
)

# ANSI color codes
RED='\033[0;31m'
YELLOW='\033[1;33m'
GREEN='\033[0;32m'
CYAN='\033[0;36m'
BOLD='\033[1m'
NC='\033[0m' # No Color

echo "🔍 Checking for generated files..."

# Get list of files to check (from CHANGED_FILES env var if set, else staged files)
STAGED_FILES=()
if [ -n "$CHANGED_FILES" ]; then
  for file in $CHANGED_FILES; do
    STAGED_FILES+=("$file")
  done
else
  while IFS= read -r file; do
    [ -n "$file" ] && STAGED_FILES+=("$file")
  done < <(git diff --cached --name-only --diff-filter=ACM)
fi

if [ ${#STAGED_FILES[@]} -eq 0 ]; then
  echo -e "${GREEN}✅ No files staged${NC}"
  exit 0
fi

GENERATOR_TOOLS_MODIFIED=false
for file in "${STAGED_FILES[@]}"; do
  for pattern in "${GENERATOR_SOURCE_PATTERNS[@]}"; do
    if [[ "$file" =~ $pattern ]]; then
      GENERATOR_TOOLS_MODIFIED=true
      break 2
    fi
  done
done

# Helper function to check if a file is manually maintained
is_manually_maintained() {
  local file="$1"
  for maintained_file in "${MANUALLY_MAINTAINED_FILES[@]}"; do
    if [ "$file" = "$maintained_file" ]; then
      return 0 # true - file is manually maintained
    fi
  done
  return 1 # false - file is not in the exception list
}

# Check each staged file against generated patterns
VIOLATIONS=()
for file in "${STAGED_FILES[@]}"; do
  # Skip files that are manually maintained exceptions
  if is_manually_maintained "$file"; then
    continue
  fi
  for pattern in "${GENERATED_PATTERNS[@]}"; do
    if echo "$file" | grep -qE "$pattern"; then
      if [ "$GENERATOR_TOOLS_MODIFIED" = true ]; then
        allowed=false
        for allowed_pattern in "${ALLOWED_WITH_GENERATORS[@]}"; do
          if [[ "$file" =~ $allowed_pattern ]]; then
            allowed=true
            break
          fi
        done
        if [ "$allowed" = true ]; then
          break
        fi
      fi
      VIOLATIONS+=("$file")
      break
    fi
  done
done

# Report violations
if [ ${#VIOLATIONS[@]} -gt 0 ]; then
  echo ""
  echo -e "${RED}╔══════════════════════════════════════════════════════════════════════════════╗${NC}"
  echo -e "${RED}║                    🚨 CONSTITUTION VIOLATION DETECTED 🚨                     ║${NC}"
  echo -e "${RED}╚══════════════════════════════════════════════════════════════════════════════╝${NC}"
  echo ""
  echo -e "${BOLD}CLAUDE.md Rule 1: Never Commit Generated Files${NC}"
  echo ""
  echo -e "${YELLOW}You are attempting to commit ${#VIOLATIONS[@]} generated file(s):${NC}"
  echo -e "${YELLOW}──────────────────────────────────────────────────────────────${NC}"
  for file in "${VIOLATIONS[@]}"; do
    echo -e "  ${RED}✗${NC} $file"
  done
  echo -e "${YELLOW}──────────────────────────────────────────────────────────────${NC}"
  echo ""
  echo -e "${CYAN}╭────────────────────────────────────────────────────────────────────────────╮${NC}"
  echo -e "${CYAN}│                    WHY THIS RULE EXISTS                                    │${NC}"
  echo -e "${CYAN}╰────────────────────────────────────────────────────────────────────────────╯${NC}"
  echo ""
  echo "  This repository uses a CI/CD automation pipeline that generates files"
  echo "  automatically. Manually committing generated files causes:"
  echo ""
  echo "    • Merge conflicts when automation regenerates the same files"
  echo "    • Double-tagging and cascade effects in the release process"
  echo "    • Inconsistency between source code and generated artifacts"
  echo "    • Difficulty tracking what changes were intentional"
  echo ""
  echo -e "${CYAN}╭────────────────────────────────────────────────────────────────────────────╮${NC}"
  echo -e "${CYAN}│                    HOW CI/CD AUTOMATION WORKS                              │${NC}"
  echo -e "${CYAN}╰────────────────────────────────────────────────────────────────────────────╯${NC}"
  echo ""
  echo "  When you push changes to source files (generators, specs, templates),"
  echo "  the ${BOLD}on-merge.yml${NC} workflow automatically:"
  echo ""
  echo "    1. Detects changes to generator tools or specifications"
  echo "    2. Runs the appropriate generators:"
  echo "       • tools/generate-all-schemas.go → *_resource.go, *_data_source.go"
  echo "       • tools/generate-examples.go    → examples/resources/, examples/data-sources/"
  echo "       • tools/transform-docs.go       → docs/resources/, docs/data-sources/"
  echo "       • tfplugindocs                  → docs/functions/"
  echo "    3. Creates a consolidated PR with all regenerated files"
  echo "    4. Handles tagging and release (ONCE, avoiding double-tags)"
  echo ""
  echo -e "${CYAN}╭────────────────────────────────────────────────────────────────────────────╮${NC}"
  echo -e "${CYAN}│                    HOW TO FIX THIS                                         │${NC}"
  echo -e "${CYAN}╰────────────────────────────────────────────────────────────────────────────╯${NC}"
  echo ""
  echo "  ${BOLD}Step 1:${NC} Unstage generated files that have no source change:"
  echo ""
  echo -e "    ${GREEN}git restore --staged ${VIOLATIONS[*]}${NC}"
  echo ""
  echo "  ${BOLD}Step 2:${NC} Commit only the SOURCE files (generators, specs, templates):"
  echo ""
  echo "    • To update resources:  Edit ${BOLD}tools/generate-all-schemas.go${NC}"
  echo "    • To update docs:       Edit ${BOLD}tools/transform-docs.go${NC} or ${BOLD}templates/${NC}"
  echo "    • To update examples:   Edit ${BOLD}tools/generate-examples.go${NC}"
  echo "    • To add new resources: Edit ${BOLD}docs/specifications/api/*.json${NC}"
  echo ""
  echo "  ${BOLD}Step 3:${NC} When a generator source did change, regenerate its outputs"
  echo "         and stage both. CI validates that the committed output is reproducible."
  echo ""
  echo -e "${YELLOW}──────────────────────────────────────────────────────────────${NC}"
  echo -e "${BOLD}For more details, see:${NC}"
  echo "  • CLAUDE.md - Part 2: CI/CD Automation Rules"
  echo "  • .github/workflows/on-merge.yml - The orchestrator workflow"
  echo -e "${YELLOW}──────────────────────────────────────────────────────────────${NC}"
  echo ""
  exit 1
fi

if [ "$GENERATOR_TOOLS_MODIFIED" = true ]; then
  echo -e "${GREEN}✅ Generated outputs are paired with generator source changes${NC}"
else
  echo -e "${GREEN}✅ No generated files detected${NC}"
fi
exit 0
